import {rooms,byId,DEMO_LABEL} from './data.js';
import {mobileRooms} from './mobile-data.js';
import {mountIllustrated} from './fallback.js';
import {mountMobileDepartments} from './mobile.js';
import './style.css';
const mobilePreview=new URLSearchParams(location.search).has('mobile-preview');
if(mobilePreview)document.documentElement.classList.add('mobile-preview');
const isMobile=()=>mobilePreview||matchMedia('(max-width:600px)').matches;
const visibleRooms=()=>isMobile()?mobileRooms:rooms;
const visibleById=id=>isMobile()?mobileRooms.find(r=>r.id===id):byId(id);
const app=document.getElementById('app');let world=null,selected=null,inspect=null,activeTab='spaces';
const icon={map:'⌗',rooms:'▦',agents:'♧',mission:'◇',zoomIn:'+',zoomOut:'−',reset:'⌖'};
const safe=(v)=>String(v||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
app.innerHTML=`<header class="mast"><div class="brand"><div class="brand-symbol"><i></i><i></i><i></i><i></i></div><span><b>PULSE HQ</b><small>LA COMPAÑÍA DIGITAL</small></span></div><div class="top-center"><span class="top-dot"></span> EDIFICIO PRINCIPAL <span class="top-divider">/</span> PLANTA 01</div><div class="top-right"><span class="demo-pill">✦ Muestra visual</span><button id="directory" class="icon-button" title="Abrir directorio" aria-label="Abrir directorio de la muestra">☷</button></div></header>
<div class="workspace"><nav class="rail" aria-label="Secciones de la oficina"><div class="rail-group"><button data-tab="spaces" class="rail-button selected" aria-label="Oficina" title="Oficina">${icon.map}</button><button data-tab="agents" class="rail-button" aria-label="Agentes" title="Agentes">${icon.agents}</button><button data-tab="mission" class="rail-button" aria-label="Misiones" title="Misiones">${icon.mission}</button></div><small>01<br/>/05</small></nav>
<main class="main"><div class="viewport" id="viewport" aria-label="Edificio isométrico interactivo"><div class="loading" id="loading"><div class="loading-mark">✳</div><div class="loading-heading">Preparando tu oficina</div><p>Estamos colocando habitaciones, muebles y personajes…</p><div class="loading-track"><span id="loadBar"></span></div><small id="loadText">Cargando espacios</small></div><div class="viewer-heading"><div class="eyebrow">PULSE HQ <span> / </span> EL MUNDO</div><h1>Una oficina con vida.</h1><p>Explora los espacios y conoce al equipo.</p></div><div class="scene-note" id="scene-note">${DEMO_LABEL}</div><div class="view-tools"><button type="button" data-control="plus" aria-label="Acercar" title="Acercar">+</button><button type="button" data-control="minus" aria-label="Alejar" title="Alejar">−</button><button type="button" data-control="reset" aria-label="Ver edificio completo" title="Restablecer">⌖</button></div><div class="rooms-strip" id="rooms-strip"><div class="rooms-title">RECORRER EDIFICIO <span>↗</span></div><div class="room-buttons">${rooms.map((r,i)=>`<button type="button" data-room="${r.id}" style="--accent:${r.accent}"><span class="room-num">0${i+1}</span><span class="room-button-name">${r.short}</span></button>`).join('')}</div></div><div class="instructions">DESLIZA PARA EXPLORAR <span>·</span> PELLIZCA PARA ACERCAR <span>·</span> TOCA UNA SALA</div></div>
<div id="fallback" class="fallback" hidden><div class="fallback-box"><span>▦</span><h2>Vista accesible del edificio</h2><p>Tu navegador no pudo abrir la escena 3D. Puedes seguir explorando cada espacio desde aquí.</p><div class="fallback-rooms">${rooms.map(r=>`<button data-room="${r.id}">${safe(r.name)} ↗</button>`).join('')}</div><button data-action="retry">Intentar de nuevo</button></div></div></main>
<aside class="inspector" id="inspector" hidden aria-live="polite"><button class="inspector-close" data-action="close" aria-label="Cerrar panel">×</button><div class="inspector-body" id="inspector-body"></div></aside></div>
<nav class="mobile-nav" aria-label="Secciones de la muestra"><button data-tab="spaces" class="selected">⌂ <small>Oficina</small></button><button data-tab="agents">♧ <small>Agentes</small></button><button data-tab="mission">◇ <small>Misiones</small></button></nav>`;
const viewport=document.getElementById('viewport'),fallback=document.getElementById('fallback'),loading=document.getElementById('loading'),inspector=document.getElementById('inspector'),panel=document.getElementById('inspector-body');
function updatePressed(){document.querySelectorAll('[data-room]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.room===selected)))}
function inspectRoom(id,agent=false){const r=visibleById(id);if(!r)return;selected=id;const staffed=r.agent&&r.kind!=='space';inspect=agent&&staffed?'agent':'room';updatePressed();const all=document.querySelectorAll('.room-buttons [data-room]');all.forEach(x=>x.classList.toggle('active',x.dataset.room===id));const list=visibleRooms();const atlas=r.atlas==='team-a'||r.atlas==='team-b'?`${r.atlas}-atlas-v1`:'pulse-agents-pixel-atlas-v1';const pos=r.sprite*(r.atlas==='original'?25:100/3);const size=r.atlas==='original'?500:400;
 panel.innerHTML=agent&&staffed?`<div class="inspector-kicker">AGENTE / PERSONAJE DE MUESTRA</div><div class="person-portrait" style="--accent:${r.accent};--sprite-pos:${pos}%;--sprite-size:${size}%;--sprite-atlas:url('/assets/characters/${atlas}.webp')"><span class="sprite-cell" role="img" aria-label="Retrato pixel art de ${safe(r.agent)}"></span></div><h2>${safe(r.agent)}</h2><p class="inspector-lead">${safe(r.title)}</p><div class="profile-line"><span>ÁREA</span><b>${safe(r.name)}</b></div><div class="profile-line"><span>ESTADO</span><b>Sin conexión</b></div><div class="profile-line"><span>TAREA ACTUAL</span><b>No consultada</b></div><p class="explain">Este personaje muestra la dirección artística. El prototipo no consulta tareas de producción ni ejecuta agentes.</p><button class="primary" data-action="about">Ver su espacio <span>↗</span></button>`:
 `<div class="inspector-kicker">ESPACIO / PLANTA 01</div><div class="inspector-number">${String(list.indexOf(r)+1).padStart(2,'0')} <span>— ${String(list.length).padStart(2,'0')}</span></div><div class="accent-line" style="background:${r.accent}"></div><h2>${safe(r.name)}</h2><p class="inspector-lead">${safe(r.sub)}</p><p>${safe(r.description)}</p>${staffed?`<div class="profile-line"><span>AGENTE DE MUESTRA</span><b>${safe(r.agent)} · ${safe(r.title)}</b></div>`:''}<div class="profile-line"><span>AMBIENTE</span><b>${safe(r.furniture)}</b></div><div class="profile-line"><span>CONEXIÓN</span><b>Prototipo visual aislado</b></div>${staffed?`<button class="primary" data-action="agent">Conocer a ${safe(r.agent)} <span>↗</span></button>`:''}`;
 inspector.hidden=false;world?.focus(id);
}
function openOverview(kind){selected=null;inspect=kind;updatePressed();const list=visibleRooms();if(kind==='agents')panel.innerHTML=`<div class="inspector-kicker">CONOCE AL EQUIPO</div><h2>Personas detrás de cada espacio.</h2><p class="inspector-lead">${list.filter(r=>r.agent&&r.kind!=='space').length} personajes para evaluar la dirección visual.</p><div class="overview-list">${list.filter(r=>r.agent&&r.kind!=='space').map(r=>`<button data-agent="${r.id}"><i style="background:${r.accent}"></i><span><b>${safe(r.agent)}</b><small>${safe(r.title)}</small></span><em>↗</em></button>`).join('')}</div><p class="explain">Los nombres son provisionales; los contratos profesionales existentes permanecen en PULSE HQ.</p>`;
 else if(kind==='mission')panel.innerHTML=`<div class="inspector-kicker">GESTIÓN DE MISIONES</div><h2>Un flujo que debe tener evidencia.</h2><p class="inspector-lead">La visualización futura seguirá los registros reales del servidor.</p><div class="flow">${['Dirección define el objetivo','Inteligencia valida el mercado','Marketing desarrolla la estrategia','Creatividad prepara materiales','Finanzas revisa viabilidad','El CEO aprueba la propuesta'].map((v,i)=>`<div><span>${String(i+1).padStart(2,'0')}</span><b>${v}</b></div>`).join('')}</div><p class="explain">Ejemplo de arquitectura. No es una misión en ejecución. Los pasos reales se integrarán tras aprobar la dirección visual.</p>`;
 else {panel.innerHTML=`<div class="inspector-kicker">DIRECTORIO DE ESPACIOS</div><h2>Explora tu compañía.</h2><p class="inspector-lead">La muestra incluye ${list.length} ambientes ilustrados.</p><div class="overview-list">${list.map(r=>`<button data-room="${r.id}"><i style="background:${r.accent}"></i><span><b>${safe(r.name)}</b><small>${safe(r.sub)}</small></span><em>↗</em></button>`).join('')}</div><p class="explain">La conexión con agentes y tareas reales sigue pendiente de validación.</p>`}
 inspector.hidden=false;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('selected',b.dataset.tab===kind));
}
async function init(){loading.hidden=false;fallback.hidden=true;world?.destroy();world=null;let graphicsFailed=false;
 if(matchMedia('(max-width:600px)').matches||mobilePreview){world=mountMobileDepartments(viewport,{onRoom:id=>inspectRoom(id),onAgent:id=>inspectRoom(id,true)});loading.hidden=true;return}
 const showIllustrated=()=>{if(world?.illustrated)return;world?.destroy();world=mountIllustrated(viewport,{onRoom:id=>inspectRoom(id),onAgent:id=>inspectRoom(id,true)});world.illustrated=true;loading.hidden=true;document.getElementById('scene-note').textContent='OFICINA ILUSTRADA · MUESTRA SIN CONEXIÓN'};
 let mountWorld;try{({mountWorld}=await import('./world.js'))}catch(e){console.warn('No se pudo cargar la escena 3D',e);showIllustrated();return}
 world=await mountWorld(viewport,{onRoom:id=>inspectRoom(id),onAgent:id=>inspectRoom(id,true),onProgress:(done,total)=>{document.getElementById('loadBar').style.width=`${Math.round(done/total*100)}%`;document.getElementById('loadText').textContent=`${done} / ${total} recursos`},onReady:()=>{loading.hidden=true},onError:(e)=>{console.warn('WebGL no disponible; se muestra la oficina ilustrada',e);graphicsFailed=true;queueMicrotask(()=>{if(world?.ok&&!world.illustrated)showIllustrated()})}});
 if(graphicsFailed||!world?.ok)showIllustrated()}
app.addEventListener('click',e=>{let r=e.target.closest('[data-room]');if(r){inspectRoom(r.dataset.room);return}let a=e.target.closest('[data-agent]');if(a){inspectRoom(a.dataset.agent,true);return}let tab=e.target.closest('[data-tab]');if(tab){activeTab=tab.dataset.tab;document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('selected',x.dataset.tab===activeTab));if(activeTab==='spaces'){inspector.hidden=true;world?.reset()}else openOverview(activeTab);return}let c=e.target.closest('[data-control]');if(c){c.dataset.control==='reset'?world?.reset():world?.zoom(c.dataset.control==='plus'?1:-1);return}let action=e.target.closest('[data-action]')?.dataset.action;if(action==='close'){inspector.hidden=true;return}if(action==='agent'&&selected)inspectRoom(selected,true);if(action==='about'&&selected)inspectRoom(selected);if(action==='retry')init()});
document.getElementById('directory').onclick=()=>openOverview('directory');document.addEventListener('keydown',e=>{if(e.key==='Escape')inspector.hidden=true;if(e.key==='+'||e.key==='=')world?.zoom(1);if(e.key==='-')world?.zoom(-1);if(e.key==='Home')world?.reset()});
init();
matchMedia('(max-width:600px)').addEventListener('change',()=>init());
